func newPerformanceReviewTemplate() unsafe.Pointer {
	return unsafe.Pointer(new(workerreview.PerformanceReviewTemplate))
}

func newNPerformanceReviewTemplate(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]workerreview.PerformanceReviewTemplate, n)))
}

func ptrPerformanceReviewTemplate(p unsafe.Pointer, c int32) any {
	r := (*workerreview.PerformanceReviewTemplate)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return &r.Code
	case 4:
		return &r.Name
	case 5:
		return &r.Description
	case 6:
		return (*string)(unsafe.Pointer(&r.Status))
	case 7:
		return &r.IsDefault
	case 8:
		return &r.CadenceMonths
	case 9:
		return &r.Items
	case 10:
		return &r.Version
	case 11:
		return &r.CreatedAt
	case 12:
		return &r.UpdatedAt
	case 13:
		return &r.SearchVector
	}
	return nil
}

func valuePerformanceReviewTemplate(p unsafe.Pointer, c int32) any {
	r := (*workerreview.PerformanceReviewTemplate)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return r.Code
	case 4:
		return r.Name
	case 5:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 6:
		return string(r.Status)
	case 7:
		return r.IsDefault
	case 8:
		if r.CadenceMonths == nil {
			return nil
		}
		return *r.CadenceMonths
	case 9:
		if r.Items == nil {
			return keel.EmptyJSONArray
		}
		return r.Items
	case 10:
		return r.Version
	case 11:
		return r.CreatedAt
	case 12:
		return r.UpdatedAt
	case 13:
		return r.SearchVector
	}
	return nil
}

